Weave.tests.asyncCases.networkRejectsNonOkResponse = () => Weave.tests.rejectsWith(Weave.library.control.errors.http, Weave.library.network.checkResponse(Weave.tests.failedResponse));
Weave.tests.asyncCases.networkRunsErrorHook = () => Weave.library.composition.then(reason => reason.seen === true)(Weave.tests.recovered(Weave.tests.withErrorHook()));
Weave.tests.asyncCases.networkWrapsUntypedRejection = () => Weave.tests.rejectsWith(Weave.library.control.errors.network, Weave.library.network.reportError({ name: 'Whatever' }));
Weave.tests.asyncCases.effectsIgnoreCancelledResolves = () => Weave.library.composition.then(Weave.library.predicates.isNil)(Weave.library.effects.ignoreCancelled(Weave.tests.cancelledEffect()));
Weave.tests.asyncCases.effectsCancelledRejectionIsNamed = () => Weave.tests.rejectsWith(Weave.library.control.errors.cancelled, Weave.tests.cancelledEffect());

/* async helpers: the fixtures the async rows share, kept out of the rows themselves. */
Weave.tests.failedResponse = { ok: false, status: 404, url: '/missing', headers: { get: Weave.library.composition.noop } };
Weave.tests.rejectsWith = (row, promise) => Weave.library.control.recover(Weave.library.composition.then(Weave.library.composition.never)(promise))(reason => Weave.library.control.isError(row, reason));
Weave.tests.recovered = promise => Weave.library.control.recover(promise)(Weave.library.composition.identity);
Weave.tests.flaky = state => () => Weave.library.control.either(() => state.tries > 1, () => Weave.library.composition.resolved('third'), () => Weave.tests.failOnce(state))(state);
Weave.tests.failOnce = state => Weave.library.composition.rejected(Object.assign(state, { tries: state.tries + 1 }));
Weave.tests.markHook = reason => Weave.library.composition.merge(reason, { seen: true });
Weave.tests.withErrorHook = () => Weave.tests.releaseHook(Weave.library.network.reportError(Weave.tests.pushHook()));
Weave.tests.pushHook = () => (Weave.library.network.hooks.onError.push(Weave.tests.markHook), { name: 'Whatever' });
Weave.tests.releaseHook = promise => (Weave.library.network.hooks.onError.pop(), promise);
Weave.tests.cancelledEffect = () => Weave.library.composition.rejected(Weave.library.control.error(Weave.library.control.errors.cancelled, {}));
/* resource rows: the async half of the request pattern, resolved by hand through a deferred. */
Weave.tests.asyncCases.patternsResourceShowsWhatItLoaded = () => Weave.library.composition.then(text => text.includes('landed'))(Weave.tests.withResource(Weave.tests.pending()));
Weave.tests.asyncCases.patternsResourceOffersARetry = () => Weave.library.composition.then(handle => Weave.tests.resourceText(handle).includes(Weave.library.patterns.labels.retry))(Weave.tests.afterFailure(Weave.tests.brokenResource(Weave.tests.pending())));
Weave.tests.asyncCases.patternsResourceRemembersWhyItFailed = () => Weave.library.composition.then(handle => Weave.library.control.isError(Weave.library.control.errors.network, handle.state.reason))(Weave.tests.afterFailure(Weave.tests.brokenResource(Weave.tests.pending())));
Weave.tests.asyncCases.patternsResourceRetriesOnDemand = () => Weave.library.composition.then(handle => Weave.tests.retried(handle))(Weave.tests.afterFailure(Weave.tests.brokenResource(Weave.tests.pending())));

Weave.tests.asyncCheck = ([name, test]) => Weave.library.composition.then(ok => Weave.tests.report(name, ok === true))(Weave.tests.settled(test));
Weave.tests.settled = test => Weave.library.control.recover(Weave.library.composition.resolved(Weave.library.control.attemptOr(test, false)()))(Weave.library.composition.never);
Weave.tests.runAsync = () => Weave.library.composition.all(Weave.library.composition.pairs(Weave.tests.asyncCases).map(Weave.tests.asyncCheck));
Weave.tests.runAll = () => Weave.library.composition.then(Weave.tests.totalWith(Weave.tests.run().total))(Weave.tests.runAsync());
Weave.tests.totalWith = base => list => Weave.tests.summary(base + list.length);
